<script>  import { SECTIONS, navStore } from '../stores/navigation.svelte.js';  import { getStrings } from '../strings.svelte.js';const strings = $derived(getStrings());  function select(id) {    navStore.current = id;  }</script><nav class="tabs no-select" aria-label="Sections">  {#each SECTIONS as section (section.id)}    {@const Icon = section.icon}    <button      type="button"      class="tabs__item"      class:active={navStore.current === section.id}      onclick={() => select(section.id)}      aria-current={navStore.current === section.id ? 'page' : undefined}    >      <span class="tabs__icon" aria-hidden="true">        <Icon size={18} strokeWidth={2} />      </span>      <span class="tabs__label">{strings.sections[section.id]}</span>    </button>  {/each}</nav><style>  .tabs { display: flex; flex-direction: column; gap: var(--space-1); padding: var(--space-2); }  .tabs__item { display: flex; align-items: center; gap: var(--space-3); min-height: var(--touch-target); padding: var(--space-2) var(--space-3); border-radius: var(--radius-md); text-align: left; font-size: var(--font-size-base); color: var(--text-secondary); background: transparent; transition: background var(--transition-fast), color var(--transition-fast); }  .tabs__item:hover { background: var(--bg-elevated-2); color: var(--text-primary); }  .tabs__item.active { background: var(--accent-dim); color: var(--accent); }  .tabs__icon { display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; opacity: 0.85; }  .tabs__item.active .tabs__icon { opacity: 1; }  .tabs__label { flex: 1; }</style>